const size=value=>Buffer.byteLength(value,'utf8');
export function select(record,question,budgetBytes){const header='本地文档阅读记忆（模型根据页图像整理，可能存在识别误差；原文可回查）：\n'+JSON.stringify(record.document)+'\n';const full=header+record.overview+'\n'+record.pages.map(page=>JSON.stringify(page)).join('\n');if(size(full)<=budgetBytes)return{text:full,pages:record.completedPages};
 const index=record.pages.map(page=>String(page.page)).join(',');let text=header+'全文概览：'+record.overview+'\n已建立记忆的页码：'+index+'\n本轮仅附相关页记忆；需要其他细节时调用 read_document_memory，需要验证图形时调用 revisit_document_page。\n';if(size(text)>budgetBytes)throw Object.assign(new Error('全文概览和页码索引超过容量，请提高上下文设置'),{code:'CONTEXT_LIMIT'});
 const terms=[...new Set(question.toLowerCase().match(/[\p{L}\p{N}]+/gu)??[])];const ranked=record.pages.map(page=>({page,score:terms.reduce((score,term)=>score+(JSON.stringify(page).toLowerCase().includes(term)?term.length:0),0)})).sort((a,b)=>b.score-a.score||a.page.page-b.page.page),pages=[];
 for(const item of ranked){const value=JSON.stringify(item.page)+'\n';if(size(text+value)<=budgetBytes){text+=value;pages.push(item.page.page);}}return{text,pages};}
